use serde_json::Value;
use std::collections::BTreeSet;

#[test]
fn main_window_grants_only_default_and_required_window_mutations() {
    let capability: Value =
        serde_json::from_str(include_str!("../capabilities/main.json")).unwrap();
    let permissions = capability["permissions"]
        .as_array()
        .unwrap()
        .iter()
        .map(|permission| permission.as_str().unwrap())
        .collect::<BTreeSet<_>>();

    // Lifecycle, close-to-tray, and updater commands are explicit allow-* app
    // permissions generated by the app manifest (no default rule exists, so
    // every granted command is listed here and nothing else may call them).
    assert_eq!(
        permissions,
        BTreeSet::from([
            "core:default",
            "core:window:allow-close",
            "core:window:allow-minimize",
            "core:window:allow-toggle-maximize",
            "allow-app-get-launch-context",
            "allow-app-stage-shutdown-checkpoint",
            "allow-app-request-shutdown",
            "allow-app-acknowledge-shutdown",
            "allow-app-cancel-shutdown",
            "allow-app-confirm-and-execute-shutdown",
            "allow-window-hide-to-tray-if-enabled",
            "allow-window-set-minimize-to-tray-on-close",
            "allow-update-get-status",
            "allow-update-check",
            "allow-update-download",
            "allow-update-install",
        ])
    );
}
